import json, numpy as np
X=np.load('X.npy');Y=np.load('Y.npy');meta=json.load(open('meta.json'))
NAMES=meta['names'];P=np.array(meta['P']);T=np.array(meta['T'])
def ridge_fit(Xtr,Ytr,lam):
    mu=Xtr.mean(0); sd=Xtr.std(0); sd[sd<1e-9]=1.0
    Z=np.hstack([(Xtr-mu)/sd,np.ones((len(Xtr),1))])
    A=Z.T@Z + lam*np.eye(Z.shape[1]); A[-1,-1]-=lam
    return mu,sd,np.linalg.solve(A, Z.T@Ytr)
def ridge_pred(m,Xte):
    mu,sd,w=m
    return np.hstack([(Xte-mu)/sd,np.ones((len(Xte),1))])@w
def lopo(cols,lam):
    maes=[]
    for pid in sorted(set(P)):
        tr=P!=pid; te=P==pid
        m=ridge_fit(X[tr][:,cols],Y[tr],lam)
        pr=ridge_pred(m,X[te][:,cols])
        maes.append(np.mean(np.abs(pr-Y[te])))
    return float(np.mean(maes))
best=[];rem=list(range(len(NAMES)));cur=1e9
for step in range(10):
    cand=None
    for j in rem:
        for lam in [3,10,30,100]:
            v=lopo(best+[j],lam)
            if cand is None or v<cand[0]: cand=(v,j,lam)
    if cand[0]<cur-0.001:
        cur=cand[0];best.append(cand[1]);rem.remove(cand[1])
        print(step,'%.4f'%cur,[NAMES[i] for i in best],'lam',cand[2])
    else:
        print('stop at',step,'%.4f'%cand[0]); break
json.dump({'best':best},open('best.json','w'))
EOF
