import json, numpy as np
X=np.load('X.npy');Y=np.load('Y.npy');meta=json.load(open('meta.json'))
NAMES=meta['names'];P=np.array(meta['P'])
pids=sorted(set(P))
def fit(Xtr,Ytr,lam):
    mu=Xtr.mean(0); sd=Xtr.std(0); sd[sd<1e-9]=1.0
    Z=np.hstack([(Xtr-mu)/sd,np.ones((len(Xtr),1))])
    A=Z.T@Z + lam*np.eye(Z.shape[1]); A[-1,-1]-=lam
    return mu,sd,np.linalg.solve(A, Z.T@Ytr)
def pred(m,Xte):
    mu,sd,w=m
    return np.hstack([(Xte-mu)/sd,np.ones((len(Xte),1))])@w
def cv(cols,lam,subset):
    maes=[]
    for pid in subset:
        tr=np.isin(P,[p for p in subset if p!=pid]); te=P==pid
        m=fit(X[tr][:,cols],Y[tr],lam)
        maes.append(np.mean(np.abs(pred(m,X[te][:,cols])-Y[te])))
    return float(np.mean(maes))
def greedy(subset,maxk=5):
    best=[];rem=list(range(len(NAMES)));cur=1e9;blam=100
    for _ in range(maxk):
        cand=None
        for j in rem:
            for lam in [3,30,100]:
                v=cv(best+[j],lam,subset)
                if cand is None or v<cand[0]: cand=(v,j,lam)
        if cand[0]<cur-0.002:
            cur=cand[0];best.append(cand[1]);rem.remove(cand[1]);blam=cand[2]
        else: break
    return best,blam,cur
outer=[]
sel_counts={}
for pid in pids:
    sub=[p for p in pids if p!=pid]
    cols,lam,_=greedy(sub)
    m=fit(X[np.isin(P,sub)][:,cols],Y[np.isin(P,sub)],lam)
    te=P==pid
    e=np.mean(np.abs(pred(m,X[te][:,cols])-Y[te]))
    outer.append(e)
    for c in cols: sel_counts[NAMES[c]]=sel_counts.get(NAMES[c],0)+1
    print(pid,'%.3f'%e,[NAMES[c] for c in cols],lam,flush=True)
print('nested pbMAE %.4f'%np.mean(outer))
print(sorted(sel_counts.items(),key=lambda x:-x[1]))
