import json, numpy as np
X=np.load('X.npy');Y=np.load('Y.npy');meta=json.load(open('meta.json'))
NAMES=meta['names'];P=np.array(meta['P'])
idx={n:i for i,n in enumerate(NAMES)};pids=sorted(set(P))
def fit(Xtr,Ytr,lam):
    mu=Xtr.mean(0); sd=Xtr.std(0); sd[sd<1e-9]=1.0
    Z=np.hstack([(Xtr-mu)/sd,np.ones((len(Xtr),1))])
    A=Z.T@Z + lam*np.eye(Z.shape[1]); A[-1,-1]-=lam
    return mu,sd,np.linalg.solve(A, Z.T@Ytr)
def pred(m,Xte):
    mu,sd,w=m
    return np.hstack([(Xte-mu)/sd,np.ones((len(Xte),1))])@w
models={'B':(['sqrt_elapsed','watts','cumwork_per_kg','bmi','bsa_per_mass'],3),
        'F':(['sqrt_elapsed','watts','cumwork_per_kg','hr','skin','bmi','age'],100),
        'C':(['sqrt_elapsed','watts','cumwork_per_kg','hr','hr_mean_all','skin','skin_rise','amb','hum','bmi','age','bsa_per_mass'],100)}
preds={}
for k,(ns,lam) in models.items():
    cols=[idx[n] for n in ns];pr=np.zeros(len(Y))
    for pid in pids:
        tr=P!=pid;te=P==pid
        pr[te]=pred(fit(X[tr][:,cols],Y[tr],lam),X[te][:,cols])
    preds[k]=pr
def pb(pr):
    return float(np.mean([np.mean(np.abs(pr[P==p]-Y[P==p])) for p in pids]))
for k in preds: print(k,'%.4f'%pb(preds[k]))
for w in [0.3,0.4,0.5,0.6,0.7]:
    print('B/F',w,'%.4f'%pb(w*preds['B']+(1-w)*preds['F']), 'B/C','%.4f'%pb(w*preds['B']+(1-w)*preds['C']))
bl=0.5*preds['B']+0.5*preds['F']
print('per-person blend', {p:round(float(np.mean(np.abs(bl[P==p]-Y[P==p]))),3) for p in pids})
res=bl-Y
for h in [0.5,0.6,0.7,0.8]:
    print('h',h,'cov %.3f'%np.mean(np.abs(res)<=h),'IS %.3f'%np.mean(2*h+20*np.maximum(np.abs(res)-h,0)))
# final fit on all data
out={}
for k,(ns,lam) in models.items():
    cols=[idx[n] for n in ns]
    mu,sd,w=fit(X[:,cols],Y,lam)
    # raw-space coefs
    b=w[:-1]/sd; c=w[-1]-float(np.sum(w[:-1]*mu/sd))
    out[k]={'names':ns,'coef':[float(v) for v in b],'intercept':float(c)}
    print(k, [(n,round(float(v),5)) for n,v in zip(ns,b)], 'int',round(c,4))
json.dump(out,open('model.json','w'),indent=1)
